/**
 * Shared env-schema introspection (§7.5): the `genenv` CLIs turn zod metadata
 * into `.env.example` files, so the schema modules stay the single source of
 * truth for both validation AND docs.
 */
import type { z } from 'zod'

export interface EnvVarDoc {
	readonly key: string
	readonly description: string | undefined
	readonly defaultValue: string | undefined
	readonly required: boolean
}

// Wrapper defs we unwrap to reach the leaf schema — some only affect
// requiredness, `.default` also carries the example-file value.
const WRAPPER_TYPES = new Set([
	'default',
	'prefault',
	'optional',
	'nullable',
	'catch',
	'readonly',
	'nonoptional'
])
const NOT_REQUIRED_TYPES = new Set(['default', 'prefault', 'optional', 'nullable', 'catch'])

interface DefLike {
	readonly type: string
	readonly innerType?: z.ZodType
	readonly defaultValue?: unknown
}

function describeOne(key: string, schema: z.ZodType): EnvVarDoc {
	let cur: z.ZodType = schema
	let description: string | undefined
	let defaultValue: unknown
	let required = true
	// `.describe()` metadata may sit on ANY wrapper layer depending on call
	// order (`.describe().default()` vs `.default().describe()`) — collect the
	// first description found while unwrapping.
	for (;;) {
		const meta = cur.meta()
		description ??= typeof meta?.description === 'string' ? meta.description : undefined
		const def = cur.def as DefLike
		if (NOT_REQUIRED_TYPES.has(def.type)) required = false
		if (def.type === 'default') defaultValue = def.defaultValue
		if (!WRAPPER_TYPES.has(def.type) || !def.innerType) break
		cur = def.innerType
	}
	return {
		key,
		description,
		defaultValue: defaultValue === undefined ? undefined : String(defaultValue),
		required
	}
}

export function describeEnvSchemas(schemas: Record<string, z.ZodType>): EnvVarDoc[] {
	return Object.entries(schemas).map(([key, schema]) => describeOne(key, schema))
}

export function renderEnvExample({
	schemas,
	generatedBy,
	source
}: {
	schemas: Record<string, z.ZodType>
	/** e.g. "`huriro genenv`" — recorded in the file header. */
	generatedBy: string
	/** e.g. "packages/env/server" — where a human should edit instead. */
	source: string
}): string {
	const lines = [`# GENERATED by ${generatedBy} — edit ${source}, never this file.`, '']
	for (const doc of describeEnvSchemas(schemas)) {
		if (doc.description) lines.push(`# ${doc.description}`)
		lines.push(`${doc.key}=${doc.defaultValue ?? ''}`, '')
	}
	return lines.join('\n')
}
